def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    import heapq

    if not jobs or k <= 0:
        return 0

    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    time_nodes = len(times)
    source = time_nodes
    sink = time_nodes + 1
    node_count = time_nodes + 2
    graph = [[] for _ in range(node_count)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    add_edge(source, 0, k, 0)
    for node in range(time_nodes - 1):
        add_edge(node, node + 1, k, 0)
    add_edge(time_nodes - 1, sink, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    inf = 10**30
    potential = [inf] * node_count
    potential[source] = 0
    for _ in range(node_count - 1):
        changed = False
        for u in range(node_count):
            if potential[u] >= inf:
                continue
            base = potential[u]
            for v, cap, cost, _rev in graph[u]:
                if cap > 0 and potential[v] > base + cost:
                    potential[v] = base + cost
                    changed = True
        if not changed:
            break

    total_cost = 0
    pushed = 0
    while pushed < k:
        dist = [inf] * node_count
        dist[source] = 0
        parent = [(-1, -1)] * node_count
        heap = [(0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for ei, (v, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                nd = d + cost + potential[u] - potential[v]
                if nd < dist[v]:
                    dist[v] = nd
                    parent[v] = (u, ei)
                    heapq.heappush(heap, (nd, v))
        if dist[sink] >= inf:
            break
        for node in range(node_count):
            if dist[node] < inf:
                potential[node] += dist[node]
        add = k - pushed
        node = sink
        while node != source:
            u, ei = parent[node]
            cap = graph[u][ei][1]
            if cap < add:
                add = cap
            node = u
        if add <= 0:
            break
        node = sink
        while node != source:
            u, ei = parent[node]
            edge = graph[u][ei]
            edge[1] -= add
            graph[node][edge[3]][1] += add
            total_cost += add * edge[2]
            node = u
        pushed += add
    return -total_cost
